In JavaScript, stacks can be implemented easily using arrays:

```js
class Stack {
  constructor() {
    this.items = [];
  }
  push(element) {
    this.items.push(element);
  }
  pop() {
    return this.items.pop();
  }
  peek() {
    return this.items[this.items.length - 1];
  }
  isEmpty() {
    return this.items.length === 0;
  }
  size() {
    return this.items.length;
  }
}

const stack = new Stack();
stack.push(10);
stack.push(20);
console.log(stack.peek()); // 20
stack.pop();
console.log(stack.peek()); // 10
```

Queues can be implemented using arrays, but using `shift()` is inefficient for large queues. Here's a class-based implementation:

```js
class Queue {
  constructor() {
    this.items = [];
  }
  enqueue(element) {
    this.items.push(element);
  }
  dequeue() {
    return this.items.shift();
  }
  front() {
    return this.items[0];
  }
  isEmpty() {
    return this.items.length === 0;
  }
  size() {
    return this.items.length;
  }
}

const queue = new Queue();
queue.enqueue("A");
queue.enqueue("B");
console.log(queue.front()); // A
queue.dequeue();
console.log(queue.front()); // B
```

One of the most common stack applications is checking for balanced parentheses:

```js
function isBalanced(s) {
  let stack = [];
  let map = {
    ')': '(',
    ']': '[',
    '}': '{'
  };
  for (let char of s) {
    if (['(', '[', '{'].includes(char)) {
      stack.push(char);
    } else if ([')', ']', '}'].includes(char)) {
      if (stack.pop() !== map[char]) {
        return false;
      }
    }
  }
  return stack.length === 0;
}

console.log(isBalanced("([{}])")); // true
console.log(isBalanced("(([]))}")); // false
```

Stacks are great for reversing data:

```js
function reverseString(str) {
  let stack = [];
  for (let char of str) {
    stack.push(char);
  }
  let reversed = '';
  while (stack.length) {
    reversed += stack.pop();
  }
  return reversed;
}

console.log(reverseString("hello")); // "olleh"
```

Queues help solve streaming problems, such as finding the first non-repeating character:

```js
function firstNonRepeating(str) {
  let freq = {};
  let queue = [];

  for (let char of str) {
    freq[char] = (freq[char] || 0) + 1;
    queue.push(char);

    while (queue.length && freq[queue[0]] > 1) {
      queue.shift();
    }
  }
  return queue.length ? queue[0] : null;
}

console.log(firstNonRepeating("aabcdb")); // 'c'
```
